MagickBooleanType ComputeBezierCurve(void)
{
  double
    x,
    y;

  size_t
    i;

  MagickBooleanType
    status;

  PointInfo
    *points = NULL;

  CoefficientInfo
    *coefficients = NULL;

  x = cos(0.0);
  y = sin(0.0);

  /* Allocate memory for coefficients and points */
  coefficients = AcquireBezierCoefficients();
  if (coefficients == NULL)
    ThrowBinaryException(ResourceLimitError, "Unable to allocate Bezier coefficients", "ComputeBezierCurve");

  points = AcquirePointInfo(0, 0);
  if (points == NULL)
  {
    RelinquishMemory(coefficients);
    ThrowBinaryException(ResourceLimitError, "Unable to allocate Bezier points", "ComputeBezierCurve");
  }

  /* Compute control points */
  for (i = 0; i < 4; i++)
  {
    if (i == 3)
    {
      /* Adjust for last segment */
      points[i].x = x * 0.5;
      points[i].y = y * 0.5;
    }
    else
    {
      points[i].x = x;
      points[i].y = y;
    }
  }

  /* Compute Bezier points using the control points */
  for (i = 0; i < 4; i++)
  {
    double u = (double) i / 3.0;
    points[i].x = (1 - u) * points[0].x + u * points[3].x;
    points[i].y = (1 - u) * points[0].y + u * points[3].y;
  }

  status = TraceBezier(coefficients, points);

  RelinquishMemory(points);
  RelinquishMemory(coefficients);

  return status;
}

